import nodemailer from "nodemailer";
import { db } from "./db";
import { renderTemplate, recordEmail, wrapEmail, emailButton, appUrl as renderAppUrl } from "./email-render";
import { renderInvoiceHTML } from "./invoices";

/**
 * SMTP config comes from the Setting table (admin-editable) with env fallback.
 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
 */
async function loadSmtp() {
  const rows = await db.setting.findMany({
    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
  });
  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
  const host = s.smtp_host || process.env.SMTP_HOST || "";
  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
  return {
    host,
    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
    user: s.smtp_user || process.env.SMTP_USER || "",
    pass: s.smtp_pass || process.env.SMTP_PASS || "",
    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
    from,
  };
}

export async function mailConfigured(): Promise<boolean> {
  const c = await loadSmtp();
  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
}

function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
  if (!c.host) {
    // Local MTA fallback (Postfix/sendmail on the host)
    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
  }
  return nodemailer.createTransport({
    host: c.host,
    port: c.port,
    secure: c.secure,
    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
  });
}

/** Template keys whose emails ship the itemised invoice as an attachment. */
const INVOICE_ATTACH_TEMPLATES = new Set(["receipt", "invoice_new", "renewal_reminder"]);

export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };

/**
 * Build the invoice attachment for an email. There is no PDF library installed
 * (and we can't add dependencies), so we attach the branded, print-ready
 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
 * browser's Print → Save as PDF, matching the on-site download route.
 */
async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
  try {
    const invoice = await db.invoice.findUnique({
      where: { id: invoiceId },
      include: { user: { select: { name: true, email: true } } },
    });
    if (!invoice) return null;
    const html = renderInvoiceHTML(invoice, invoice.user);
    const number = String(invoice.number).padStart(5, "0");
    return { filename: `nxeon-invoice-${number}.html`, content: html, contentType: "text/html; charset=utf-8" };
  } catch (e) {
    console.error("[mailer] failed to build invoice attachment:", e);
    return null;
  }
}

export type SendMailOpts = {
  to: string;
  /** Explicit subject. Optional when `template` is provided. */
  subject?: string;
  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
  html?: string;
  text?: string;
  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
  template?: string;
  /** Variables for `{{placeholders}}` when rendering from a template. */
  vars?: Record<string, unknown>;
  /** Attribution for the EmailLog row. */
  userId?: string | null;
  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
  invoiceId?: string;
  /** Extra attachments. */
  attachments?: MailAttachment[];
};

/**
 * Send an email. Never throws — logs and returns false on failure so callers
 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
 * FAILED + error otherwise) for the admin Logs viewer.
 */
export async function sendMail(opts: SendMailOpts): Promise<boolean> {
  // Resolve subject/html: prefer explicit values, otherwise render the template.
  let subject = opts.subject ?? "";
  let html = opts.html ?? "";
  const templateKey = opts.template ?? null;

  if (templateKey && !opts.html) {
    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
    subject = opts.subject ?? rendered.subject;
    html = rendered.html;
  }

  // Assemble attachments (invoice auto-attaches for the relevant templates).
  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
  if (wantInvoice && opts.invoiceId) {
    const att = await invoiceAttachment(opts.invoiceId);
    if (att) attachments.push(att);
  }

  try {
    const c = await loadSmtp();
    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
      console.warn("[mailer] not configured — skipping email:", subject);
      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
      return false;
    }
    const t = transport(c);
    await t.sendMail({
      from: c.from,
      to: opts.to,
      subject,
      html,
      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
      attachments: attachments.length ? attachments : undefined,
    });
    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
    return true;
  } catch (e) {
    console.error("[mailer] send failed:", e);
    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
    return false;
  }
}

/**
 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
 * and (for billing templates) attach the invoice. Thin convenience over
 * `sendMail` for new callers.
 */
export async function sendTemplate(
  key: string,
  to: string,
  vars: Record<string, unknown> = {},
  opts: { userId?: string | null; invoiceId?: string; attachments?: MailAttachment[] } = {},
): Promise<boolean> {
  return sendMail({ to, template: key, vars, userId: opts.userId, invoiceId: opts.invoiceId, attachments: opts.attachments });
}

export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
  try {
    const c = await loadSmtp();
    const t = transport(c);
    const html = layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>");
    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html });
    await recordEmail(to, "Nxeon SMTP test", null, html, "SENT");
    return { ok: true };
  } catch (e: any) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

