"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { logEvent } from "@/lib/log";
import { sendMail, wrapEmail } from "@/lib/mailer";

type ActionState = { error?: string; ok?: boolean };

const composeSchema = z.object({
  subject: z.string().min(1, "A subject is required.").max(200),
  body: z.string().min(1, "The email body can't be empty.").max(100_000),
});

/**
 * Render an authored newsletter body to email-ready HTML.
 *
 * Non-exported (sync) so it lives happily inside a "use server" module. The
 * NewsletterComposer client keeps a byte-identical copy for its live preview —
 * keep the two in sync if you change the markdown subset here.
 *
 * If the author already wrote block-level HTML we pass it through untouched;
 * otherwise we render a small, safe markdown subset (headings, bold, italic,
 * inline code, links and bullet lists).
 */
function bodyToHtml(body: string): string {
  const src = body.trim();
  if (!src) return "";

  if (/<(p|div|table|h[1-6]|ul|ol|li|img|br|a|span|section|center|strong|em|blockquote)\b/i.test(src)) {
    return src;
  }

  const inline = (t: string) =>
    t
      .replace(
        /\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g,
        '<a href="$2" style="color:#8a70fb;text-decoration:none">$1</a>',
      )
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>")
      .replace(
        /`([^`]+)`/g,
        '<code style="background:#0a101f;padding:2px 5px;border-radius:5px">$1</code>',
      );

  const lines = src.split(/\r?\n/);
  const out: string[] = [];
  let list: string[] = [];
  let para: string[] = [];

  const flushList = () => {
    if (list.length) {
      out.push(
        `<ul style="margin:12px 0;padding-left:20px">${list
          .map((li) => `<li style="margin:4px 0">${inline(li)}</li>`)
          .join("")}</ul>`,
      );
      list = [];
    }
  };
  const flushPara = () => {
    if (para.length) {
      out.push(`<p style="margin:0 0 14px">${inline(para.join(" "))}</p>`);
      para = [];
    }
  };

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) {
      flushList();
      flushPara();
      continue;
    }
    const h = /^(#{1,3})\s+(.*)$/.exec(line);
    if (h) {
      flushList();
      flushPara();
      const level = h[1].length;
      const size = level === 1 ? 22 : level === 2 ? 18 : 15;
      out.push(
        `<h${level} style="margin:18px 0 10px;font-size:${size}px;color:#ffffff">${inline(h[2])}</h${level}>`,
      );
      continue;
    }
    if (/^[-*]\s+/.test(line)) {
      flushPara();
      list.push(line.replace(/^[-*]\s+/, ""));
      continue;
    }
    flushList();
    para.push(line);
  }
  flushList();
  flushPara();
  return out.join("\n");
}

/** Create a new campaign draft. Wired to a <form> via useActionState. */
export async function createCampaign(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const parsed = composeSchema.safeParse({
    subject: formData.get("subject"),
    body: formData.get("body"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid campaign." };
  }

  try {
    await db.newsletterCampaign.create({
      data: { subject: parsed.data.subject, html: parsed.data.body, status: "DRAFT" },
    });
    revalidatePath("/admin/newsletter");
    return { ok: true };
  } catch (e) {
    await logEvent("error", "newsletter.campaign.create", { message: String((e as Error)?.message ?? e) });
    return { error: "Could not save the campaign. Please try again." };
  }
}

/** Update an existing draft. Sent / sending campaigns are immutable. */
export async function updateCampaign(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const id = String(formData.get("id") ?? "");
  if (!id) return { error: "Missing campaign id." };

  const parsed = composeSchema.safeParse({
    subject: formData.get("subject"),
    body: formData.get("body"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid campaign." };
  }

  try {
    const existing = await db.newsletterCampaign.findUnique({ where: { id } });
    if (!existing) return { error: "Campaign not found." };
    if (existing.status === "SENDING" || existing.status === "SENT") {
      return { error: "This campaign has already been sent and can no longer be edited." };
    }
    await db.newsletterCampaign.update({
      where: { id },
      data: { subject: parsed.data.subject, html: parsed.data.body, status: "DRAFT" },
    });
    revalidatePath("/admin/newsletter");
    return { ok: true };
  } catch (e) {
    await logEvent("error", "newsletter.campaign.update", { id, message: String((e as Error)?.message ?? e) });
    return { error: "Could not update the campaign. Please try again." };
  }
}

/** Delete a campaign. Refused while a send is in flight. */
export async function deleteCampaign(id: string): Promise<{ error?: string }> {
  await requireArea("platform");
  try {
    const c = await db.newsletterCampaign.findUnique({ where: { id } });
    if (!c) return { error: "Campaign not found." };
    if (c.status === "SENDING") return { error: "Can't delete a campaign while it is sending." };
    await db.newsletterCampaign.delete({ where: { id } });
    revalidatePath("/admin/newsletter");
    return {};
  } catch (e) {
    await logEvent("error", "newsletter.campaign.delete", { id, message: String((e as Error)?.message ?? e) });
    return { error: "Could not delete the campaign." };
  }
}

/**
 * Send a campaign to every newsletter subscriber.
 *
 * Best-effort: marks the campaign SENDING, then walks the subscriber list one
 * message at a time via `sendMail` (which never throws and logs each attempt to
 * EmailLog). A failure to any single address is counted and skipped — it never
 * aborts the batch. A tiny per-message delay throttles the SMTP relay. On
 * completion the campaign is set SENT with the success count (or FAILED if not
 * a single message went out).
 */
export async function sendCampaign(id: string): Promise<{ error?: string; sent?: number }> {
  await requireArea("platform");

  const campaign = await db.newsletterCampaign.findUnique({ where: { id } });
  if (!campaign) return { error: "Campaign not found." };
  if (campaign.status === "SENDING") return { error: "This campaign is already being sent." };
  if (campaign.status === "SENT") return { error: "This campaign has already been sent." };

  const subscribers = await db.newsletterSubscriber.findMany({ select: { email: true } });
  if (subscribers.length === 0) return { error: "There are no subscribers to send to yet." };

  await db.newsletterCampaign.update({ where: { id }, data: { status: "SENDING" } });

  const html = wrapEmail(bodyToHtml(campaign.html));
  let sent = 0;

  try {
    for (const sub of subscribers) {
      try {
        const ok = await sendMail({ to: sub.email, subject: campaign.subject, html });
        if (ok) sent++;
      } catch (e) {
        // sendMail is documented not to throw, but stay defensive so one bad
        // address can never abort the whole run.
        await logEvent("warn", "newsletter.campaign.recipient", {
          id,
          email: sub.email,
          message: String((e as Error)?.message ?? e),
        });
      }
      // Gentle throttle so we don't hammer the relay on larger lists.
      await new Promise((r) => setTimeout(r, 40));
    }

    const status = sent > 0 ? "SENT" : "FAILED";
    await db.newsletterCampaign.update({
      where: { id },
      data: { status, sentCount: sent, sentAt: new Date() },
    });
    await logEvent("info", "newsletter.campaign.sent", {
      id,
      subject: campaign.subject,
      total: subscribers.length,
      sent,
    });
    revalidatePath("/admin/newsletter");

    if (sent === 0) {
      return { error: "No emails could be sent — check the SMTP configuration in Settings.", sent: 0 };
    }
    return { sent };
  } catch (e) {
    await db.newsletterCampaign
      .update({ where: { id }, data: { status: "FAILED", sentCount: sent } })
      .catch(() => {});
    await logEvent("error", "newsletter.campaign.send", { id, message: String((e as Error)?.message ?? e) });
    revalidatePath("/admin/newsletter");
    return { error: "The send failed unexpectedly. Some messages may have gone out.", sent };
  }
}

