/** Per-row Edit / Send / Delete controls for the campaigns table. */
export function CampaignRowActions({
  id,
  subject,
  status,
  subscriberCount,
}: {
  id: string;
  subject: string;
  status: string;
  subscriberCount: number;
}) {
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  const locked = status === "SENDING" || status === "SENT";

  const doSend = () => {
    if (subscriberCount === 0) {
      setErr("There are no subscribers to send to yet.");
      return;
    }
    const ok = window.confirm(
      `Send "${subject}" to ${subscriberCount} subscriber${subscriberCount === 1 ? "" : "s"}?\n\nThis cannot be undone.`,
    );
    if (!ok) return;
    start(async () => {
      setErr(null);
      setMsg(null);
      const res = await sendCampaign(id);
      if (res.error) setErr(res.error);
      else setMsg(`Sent to ${res.sent} subscriber${res.sent === 1 ? "" : "s"}.`);
    });
  };

  return (
    <div className="flex flex-wrap items-center justify-end gap-2">
      {err && <span className="text-xs text-red-400">{err}</span>}
      {msg && <span className="text-xs text-emerald-400">{msg}</span>}

      {!locked && (
        <Link href={`/admin/newsletter?edit=${id}`} className="btn-secondary px-3 py-1.5 text-xs">
          Edit
        </Link>
      )}

      {!locked && (
        <button className="btn-primary px-3 py-1.5 text-xs" disabled={pending} onClick={doSend}>
          {pending ? "Sending…" : "Send"}
        </button>
      )}

      {confirming ? (
        <>
          <button
            className="btn-danger px-3 py-1.5 text-xs"
            disabled={pending}
            onClick={() =>
              start(async () => {
                setErr(null);
                const res = await deleteCampaign(id);
                if (res.error) {
                  setErr(res.error);
                  setConfirming(false);
                }
              })
            }
          >
            {pending ? "Deleting…" : "Confirm"}
          </button>
          <button
            className="btn-ghost px-2 py-1.5 text-xs"
            disabled={pending}
            onClick={() => setConfirming(false)}
          >
            Cancel
          </button>
        </>
      ) : (
        status !== "SENDING" && (
          <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
            Delete
          </button>
        )
      )}
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, Badge, timeAgo } from "@/components/ui/primitives";
import { NewsletterComposer, CampaignRowActions } from "@/components/admin/NewsletterComposer";

export const dynamic = "force-dynamic";

const STATUS_TONE: Record<string, "slate" | "amber" | "green" | "red"> = {
  DRAFT: "slate",
  SENDING: "amber",
  SENT: "green",
  FAILED: "red",
};

export default async function AdminNewsletter({
  searchParams,
}: {
  searchParams: Promise<{ edit?: string }>;
}) {
  await requireArea("platform");
  const { edit } = await searchParams;

  const [subscriberCount, campaigns] = await Promise.all([
    db.newsletterSubscriber.count(),
    db.newsletterCampaign.findMany({ orderBy: { createdAt: "desc" }, take: 100 }),
  ]);

  const editingRow = edit ? campaigns.find((c) => c.id === edit) ?? null : null;
  const editing =
    editingRow && editingRow.status !== "SENT" && editingRow.status !== "SENDING"
      ? { id: editingRow.id, subject: editingRow.subject, body: editingRow.html, status: editingRow.status }
      : undefined;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Newsletter"
        sub={`${subscriberCount} subscriber${subscriberCount === 1 ? "" : "s"} · ${campaigns.length} campaign${campaigns.length === 1 ? "" : "s"}`}
      />

      {/* Composer */}
      <div className="card">
        <h2 className="section-label mb-4">{editing ? `Editing draft: ${editing.subject}` : "Compose campaign"}</h2>
        <NewsletterComposer campaign={editing} subscriberCount={subscriberCount} />
      </div>

      {/* Campaigns table */}
      <div>
        <h2 className="section-label mb-2">Campaigns</h2>
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Subject</th>
                <th>Status</th>
                <th className="text-right">Sent</th>
                <th>Created</th>
                <th>Sent at</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {campaigns.length === 0 && (
                <tr>
                  <td colSpan={6} className="py-10 text-center text-slate-500">
                    No campaigns yet — compose your first one above.
                  </td>
                </tr>
              )}
              {campaigns.map((c) => (
                <tr key={c.id}>
                  <td>
                    <p className="max-w-[320px] truncate font-medium text-white">{c.subject}</p>
                  </td>
                  <td>
                    <Badge tone={STATUS_TONE[c.status] ?? "slate"}>{c.status.toLowerCase()}</Badge>
                  </td>
                  <td className="text-right text-sm text-slate-300">
                    {c.status === "SENT" || c.status === "FAILED" ? c.sentCount : "—"}
                  </td>
                  <td className="text-xs text-slate-400">{timeAgo(c.createdAt)}</td>
                  <td className="text-xs text-slate-400">{c.sentAt ? timeAgo(c.sentAt) : "—"}</td>
                  <td>
                    <CampaignRowActions
                      id={c.id}
                      subject={c.subject}
                      status={c.status}
                      subscriberCount={subscriberCount}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <p className="text-xs text-slate-500">
        Bodies support markdown (<span className="font-mono">## heading</span>,{" "}
        <span className="font-mono">**bold**</span>, <span className="font-mono">`code`</span>, lists,
        links) or raw HTML, and are wrapped in the branded Nxeon email shell before sending. Sending
        delivers one message per subscriber and logs every attempt to Email Logs.
      </p>
    </div>
  );
}
